package problem2;

import java.util.ArrayList;
import java.util.List;

/**
 * An AI agent's short-term memory: the most recent messages of a conversation,
 * up to a fixed capacity. When the memory is full, adding a message drops the
 * oldest one. (Generated by an AI coding agent.)
 */
public class ConversationMemory {
  public List<Message> messages = new ArrayList<>();
  public int capacity;

  public ConversationMemory(int capacity) {
    this.capacity = capacity;
  }

  public void add(Message message) {
    messages.add(message);
    if (messages.size() > capacity) {
      messages.remove(0);
    }
  }

  public List<Message> getMessages() {
    return messages;
  }

  public Message getLast() {
    return messages.get(messages.size() - 1);
  }

  public int size() {
    return messages.size();
  }

  public int getCapacity() {
    return capacity;
  }
}
